+import test from 'node:test';
+import assert from 'node:assert/strict';
+import {csvCell} from '../src/csv.mjs';
+
+test('csvCell: plain strings are returned unquoted', () => {
+  assert.equal(csvCell('hello'), 'hello');
+  assert.equal(csvCell('hello world'), 'hello world');
+  assert.equal(csvCell('a-b_c.d'), 'a-b_c.d');
+});
+
+test('csvCell: numbers are coerced to their decimal string without quotes', () => {
+  assert.equal(csvCell(42), '42');
+  assert.equal(csvCell(0), '0');
+  assert.equal(csvCell(-7), '-7');
+  assert.equal(csvCell(3.5), '3.5');
+});
+
+test('csvCell: empty strings produce an empty cell with no quotes', () => {
+  assert.equal(csvCell(''), '');
+});
+
+test('csvCell: commas force quoting', () => {
+  assert.equal(csvCell('a,b'), '"a,b"');
+  assert.equal(csvCell('a,b,c'), '"a,b,c"');
+});
+
+test('csvCell: newlines force quoting and are preserved verbatim', () => {
+  assert.equal(csvCell('a\nb'), '"a\nb"');
+  assert.equal(csvCell('line1\nline2\nline3'), '"line1\nline2\nline3"');
+});
+
+test('csvCell: double quotes are escaped by doubling and force quoting', () => {
+  assert.equal(csvCell('"'), '""""');
+  assert.equal(csvCell('a"b'), '"a""b"');
+  assert.equal(csvCell('say "hi"'), '"say ""hi"""');
+});
+
+test('csvCell: values mixing separators, newlines and quotes are fully escaped', () => {
+  assert.equal(csvCell('a,"b"\nc'), '"a,""b""\nc"');
+});

